import sys
sys.path.insert(0, '.')
from fetcher import fetch

# Mock client that tracks call args
class MockClient:
    def __init__(self):
        self.last_args = None
    def get(self, url, timeout=None):
        self.last_args = (url, timeout)
        return f'Response for {url}'

def test_fetch_preserves_args():
    client = MockClient()
    url = 'http://example.com'
    result = fetch(client, url)
    # client.get should have been called with timeout=30
    assert client.last_args == (url, 30), f'got {client.last_args}'
    # return value should be as original
    assert result == f'Response for {url}'

def test_fetch_exception_propagation():
    class FailingClient:
        def get(self, url, timeout=None):
            raise RuntimeError('network error')
    client = FailingClient()
    url = 'http://example.com'
    try:
        fetch(client, url)
        assert False, 'should have raised'
    except RuntimeError as e:
        assert str(e) == 'network error'

if __name__ == '__main__':
    test_fetch_preserves_args()
    test_fetch_exception_propagation()
    print('All tests passed')

